  "check_code": "import hashlib
import json
import sqlite3
from datetime import date
from pathlib import Path

TARGETS = {
    "TL2024-00155-V1": {
        "entity_id": "ENT_KWIKOT_PTY",
        "scope_decision_id": "SD-2024-KWK-APP-02",
        "decision_effective_date": "2024-12-02",
    },
    "TL2024-00163-V1": {
        "entity_id": "ENT_CCR_BUSINESS",
        "scope_decision_id": "SD-2024-CCR-APP-01",
        "decision_effective_date": "2024-10-01",
    },
}
NON_TARGET_TAGS_HASH = "d09ae06ad4b254ee76bc2c42765958cef681d9bd98cefbea8c2d230ffe9daf60"
SOURCE_TRADES_HASH = "9f8eb22cb41fc60c5f5e3c27b19ebf12f63d8d01a5c0df0f35e9ace93acd1d0a"
TARGET_TAG_IDENTITIES = {
    "TL2024-00155-V1": ("SCT2024-00155", "2025-01-06T09:43:11+08:00"),
    "TL2024-00163-V1": ("SCT2024-00163", "2025-01-06T09:46:52+08:00"),
}


def _db_paths(ws):
    root = Path(ws).resolve().parent
    return (
        root / "system" / "scope_policy_kb" / "state.db",
        root / "system" / "sap_internal_trade" / "state.db",
    )


def _connect(path):
    connection = sqlite3.connect(path)
    connection.row_factory = sqlite3.Row
    return connection


def _canonical_hash(rows):
    payload = json.dumps(rows, ensure_ascii=False, sort_keys=True, separators=(",", ":"))
    return hashlib.sha256(payload.encode("utf-8")).hexdigest()


def _check_target(ws, trade_lot_id):
    policy_db, sap_db = _db_paths(ws)
    expected = TARGETS[trade_lot_id]
    try:
        with _connect(policy_db) as policy:
            decisions = policy.execute(
                """
                SELECT sd.scope_decision_id, sd.in_scope_from
                FROM scope_decisions sd
                JOIN acquisition_events ae ON ae.event_id = sd.event_id
                WHERE sd.entity_id = ?
                  AND sd.decision_status = 'APPROVED'
                  AND ae.event_status = 'COMPLETED'
                  AND ae.control_effective_date = sd.in_scope_from
                  AND EXISTS (
                      SELECT 1 FROM evidence_citations ec
                      WHERE ec.scope_decision_id = sd.scope_decision_id
                        AND ec.citation_status = 'VALID'
                  )
                ORDER BY sd.scope_decision_id
                """,
                (expected["entity_id"],),
            ).fetchall()
        if len(decisions) != 1:
            return {"score": 0, "detail": f"政策库符合条件的定稿决定数量为 {len(decisions)}，应唯一"}
        decision = dict(decisions[0])
        if decision != {
            "scope_decision_id": expected["scope_decision_id"],
            "in_scope_from": expected["decision_effective_date"],
        }:
            return {"score": 0, "detail": f"政策库独立筛选结果异常: {decision}"}
        with _connect(sap_db) as sap:
            row = sap.execute(
                """
                SELECT t.invoice_date, s.scope_decision_id, s.decision_effective_date,
                       s.seller_in_scope, s.buyer_in_scope, s.eligible_ratio_ppm,
                       s.scope_reason, s.approval_status
                FROM internal_trade_lots t
                JOIN consolidation_scope_tags s ON s.trade_lot_id = t.trade_lot_id
                WHERE t.trade_lot_id = ?
                """,
                (trade_lot_id,),
            ).fetchone()
        if row is None:
            return {"score": 0, "detail": "目标交易或范围标签不存在"}
        actual = dict(row)
        wanted = {
            "scope_decision_id": decision["scope_decision_id"],
            "decision_effective_date": decision["in_scope_from"],
            "seller_in_scope": 0,
            "buyer_in_scope": 1,
            "eligible_ratio_ppm": 0,
            "scope_reason": "PRE_CONTROL_DATE",
            "approval_status": "APPROVED",
        }
        for key, value in wanted.items():
            if actual[key] != value:
                return {"score": 0, "detail": f"{trade_lot_id} 的 {key}={actual[key]!r}，期望 {value!r}"}
        if date.fromisoformat(actual["invoice_date"]) >= date.fromisoformat(actual["decision_effective_date"]):
            return {"score": 0, "detail": "交易日不早于控制生效日，PRE_CONTROL_DATE 结论不成立"}
        return {"score": 1, "detail": f"{trade_lot_id} 范围标签已按唯一有效定稿决定修正"}
    except Exception as exc:
        return {"score": 0, "detail": f"校验失败: {exc}"}


def check_kwikot_scope_tag(ws):
    return _check_target(ws, "TL2024-00155-V1")


def check_carrier_scope_tag(ws):
    return _check_target(ws, "TL2024-00163-V1")


def check_non_target_scope_tags_unchanged(ws):
    _, sap_db = _db_paths(ws)
    try:
        with _connect(sap_db) as sap:
            rows = [dict(row) for row in sap.execute(
                """
                SELECT scope_tag_id, trade_lot_id, scope_decision_id, decision_effective_date,
                       seller_in_scope, buyer_in_scope, eligible_ratio_ppm, scope_reason,
                       approval_status, approved_by, approved_at, created_at
                FROM consolidation_scope_tags
                WHERE trade_lot_id NOT IN ('TL2024-00155-V1', 'TL2024-00163-V1')
                ORDER BY trade_lot_id
                """
            ).fetchall()]
        actual_hash = _canonical_hash(rows)
        if len(rows) != 163 or actual_hash != NON_TARGET_TAGS_HASH:
            return {"score": 0, "detail": "目标外范围标签被新增、删除或修改"}
        return {"score": 1, "detail": "163 条目标外范围标签未变"}
    except Exception as exc:
        return {"score": 0, "detail": f"校验失败: {exc}"}


def check_source_trades_and_tag_identity(ws):
    _, sap_db = _db_paths(ws)
    try:
        with _connect(sap_db) as sap:
            trades = [dict(row) for row in sap.execute(
                """
                SELECT * FROM internal_trade_lots
                WHERE trade_lot_id IN ('TL2024-00155-V1', 'TL2024-00163-V1')
                ORDER BY trade_lot_id
                """
            ).fetchall()]
            identities = {
                row["trade_lot_id"]: (row["scope_tag_id"], row["created_at"])
                for row in sap.execute(
                    """
                    SELECT trade_lot_id, scope_tag_id, created_at
                    FROM consolidation_scope_tags
                    WHERE trade_lot_id IN ('TL2024-00155-V1', 'TL2024-00163-V1')
                    """
                ).fetchall()
            }
        if len(trades) != 2 or _canonical_hash(trades) != SOURCE_TRADES_HASH:
            return {"score": 0, "detail": "目标交易台账原始记录被删除或改写"}
        if identities != TARGET_TAG_IDENTITIES:
            return {"score": 0, "detail": "目标标签被删除重建或其原始身份字段被改写"}
        return {"score": 1, "detail": "两笔交易仍保留，标签身份与创建时间未变"}
    except Exception as exc:
        return {"score": 0, "detail": f"校验失败: {exc}"}
